# Generated by tilefish (tilefish.im2col1d) for f16, kernel 3, stride 2, dilation 1, padding 2 before and 5 after, channel order, 80 channels. Do not edit.
# out[n, t, c * 3 + j] = x[n, c, t * 2 - 2 + j], +0.0 outside [0, L): a raw copy, i64 offsets.
import triton
import triton.language as tl


@triton.jit
def tf_im2col1d_f16_k3_s2_d1_p2x5_channel_c80(
    x,
    out,
    L,
    Lo,
    x_s0,
    x_s1,
    x_s2,
    BLOCK: tl.constexpr,
):
    t = tl.program_id(0)
    n = tl.program_id(1).to(tl.int64)
    ncol = 240
    row = n * Lo + t
    for c0 in range(0, ncol, BLOCK):
        col = c0 + tl.arange(0, BLOCK)
        cm = col < ncol
        ch = col // 3
        tap = col % 3
        pos = t * 2 - 2 + tap
        ok = cm & (pos >= 0) & (pos < L)
        v = tl.load(x + n * x_s0 + ch * x_s1 + pos * x_s2, mask=ok, other=0)
        tl.store(out + row * ncol + col, v, mask=cm)
